import{_ as a,o as t,c as s,a2 as i}from"./chunks/framework.CQxpk36T.js";const m=JSON.parse('{"title":"Film and screenshots","description":"","frontmatter":{},"headers":[],"relativePath":"en/developpement/medias.md","filePath":"en/developpement/medias.md","lastUpdated":1793574169000}'),n={name:"en/developpement/medias.md"};function d(o,e,r,h,c,l){return t(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="film-and-screenshots" tabindex="-1">Film and screenshots <a class="header-anchor" href="#film-and-screenshots" aria-label="Permalink to &quot;Film and screenshots&quot;">​</a></h1><p>The film and screenshots on this site and in the README are generated from the example house in demo mode: nothing personal appears, and one command remakes them after a visible change.</p><h2 id="screenshots" tabindex="-1">Screenshots <a class="header-anchor" href="#screenshots" aria-label="Permalink to &quot;Screenshots&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> screens</span></span></code></pre></div><p>Writes <code>docs/public/screens/*.jpg</code>: seven desktop screenshots (1920 × 1080) and three phone ones (975 × 2110). Each puts the demo in a precise state: time, weather, tab, selected building, cut floor, lamps on. Under a minute.</p><h2 id="the-film" tabindex="-1">The film <a class="header-anchor" href="#the-film" aria-label="Permalink to &quot;The film&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> video</span></span></code></pre></div><p>Writes <code>docs/public/demo.mp4</code> (1080p, H.264) and its poster <code>docs/public/demo-poster.jpg</code>. About three minutes of capture and fifteen seconds of encoding.</p><p>The script, titles and transitions are in <code>scripts/media/film.js</code>, injected into the page:</p><ul><li>a <strong>virtual clock</strong> replaces <code>performance.now</code>, <code>Date</code>, <code>requestAnimationFrame</code>, timers and CSS animations: each frame advances exactly 1/30 s, however fast the machine is;</li><li>titles, lower thirds, wipes and simulated taps are animated CSS overlays;</li><li>each frame is captured through the Chrome protocol, then piped to ffmpeg (<a href="https://github.com/eugeneware/ffmpeg-static" target="_blank" rel="noreferrer">ffmpeg-static</a>, installed with the project).</li></ul><table tabindex="0"><thead><tr><th>Variable</th><th></th></tr></thead><tbody><tr><td><code>VIDEO_GPU=0</code></td><td>Software rendering (machine without a graphics card)</td></tr><tr><td><code>VIDEO_KEEP=1</code></td><td>Keeps the captured frames</td></tr><tr><td><code>VIDEO_ENCODE_ONLY=1</code></td><td>Re-encodes the kept frames without capturing again</td></tr></tbody></table><p>Without an ffmpeg with H.264, the film comes out as WebM (VP9).</p><h2 id="the-shared-base" tabindex="-1">The shared base <a class="header-anchor" href="#the-shared-base" aria-label="Permalink to &quot;The shared base&quot;">​</a></h2><p><code>scripts/media/app.mjs</code> starts the development server (example house), launches Chromium with the graphics card and a forced pixel density, fixes randomness (same animals, same clouds every time) and waits for the scene and fonts to be ready.</p>',14)])])}const u=a(n,[["render",d]]);export{m as __pageData,u as default};
